/**
 * Row correction of sampled residual estimates for databases whose records hold several rows. The test database stores,
 * per record, a four-field varint key and a two-byte value {rows, matching rows}. Most matching rows sit in records
 * whose key does not match, which is the bias that chunk-key sampling has on chunked statement indexes.
 */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class LmdbChunkRowCorrectionTest {

	private static final String DATABASE = "rows";
	private static final int RECORDS = 50_000;
	private static final long TARGET = 2;
	private static final long OTHER = 1;
	/** Every 10th record's key carries TARGET and holds one matching row; the rest hold 5 rows, 2 matching. */
	private static final long EXACT_MATCHING_ROWS = RECORDS / 10 + (RECORDS - RECORDS / 10) * 2L;
	/**
	 * Matching rows only in the last quarter of the key range: there every 10th key carries TARGET with one matching
	 * row and the others hold 5 rows, 2 matching; the first three quarters hold 5 rows, none matching.
	 */
	private static final String CLUSTERED = "clustered";
	/** Large enough that even the rare-pattern confirmation sample (256 probes) cannot enumerate every leaf. */
	private static final int CLUSTERED_RECORDS = 400_000;
	private static final int CLUSTER_START = CLUSTERED_RECORDS * 3 / 4;
	private static final long CLUSTERED_MATCHING_ROWS = (CLUSTERED_RECORDS - CLUSTER_START) / 10
			+ (CLUSTERED_RECORDS - CLUSTER_START - (CLUSTERED_RECORDS - CLUSTER_START) / 10) * 2L;
	/** Few enough records that the estimator counts the whole range exactly over a handful of leaves. */
	private static final String SMALL = "small";
	private static final int SMALL_RECORDS = 1_000;
	/**
	 * Too many leaves for the exact small-range route, but few enough that the residual sample measures every leaf.
	 */
	private static final String MEDIUM = "medium";
	private static final int MEDIUM_RECORDS = 10_000;
	/** Few enough records that the whole range lies on one leaf. */
	private static final String TINY = "tiny";
	private static final int TINY_RECORDS = 50;
	/** A predicate that no key carries. */
	private static final long ABSENT = 3;

	private static final ChunkRowMeasure MEASURE = new ChunkRowMeasure() {
		@Override
		public long measure(ByteBuffer key, ByteBuffer value) {
			return ChunkRowMeasure.pack(value.get(value.position()), value.get(value.position() + 1));
		}

		@Override
		public int maxRowsPerRecord() {
			return 5;
		}
	};

	@TempDir
	static Path directory;

	private long environment;
	private int mainDbi;
	private LmdbPageCardinalityEstimator estimator;
	private long readTxn;

	@BeforeAll
	void createDatabase() throws IOException {
		try (MemoryStack stack = stackPush()) {
			PointerBuffer pointer = stack.mallocPointer(1);
			check(mdb_env_create(pointer));
			environment = pointer.get(0);
			check(mdb_env_set_maxdbs(environment, 8));
			check(mdb_env_set_mapsize(environment, 256L << 20));
			check(mdb_env_open(environment, directory.toAbsolutePath().toString(), 0, 0664));
			check(mdb_txn_begin(environment, NULL, 0, pointer));
			long writeTxn = pointer.get(0);
			boolean open = true;
			try {
				IntBuffer dbi = stack.mallocInt(1);
				check(mdb_dbi_open(writeTxn, (ByteBuffer) null, 0, dbi));
				mainDbi = dbi.get(0);
				check(mdb_dbi_open(writeTxn, DATABASE, MDB_CREATE, dbi));
				int rows = dbi.get(0);
				for (int record = 1; record <= RECORDS; record++) {
					boolean targetKey = record % 10 == 0;
					try (MemoryStack frame = stack.push()) {
						MDBVal key = MDBVal.calloc(frame).mv_data(frame.bytes(key(record, targetKey ? TARGET : OTHER)));
						MDBVal value = MDBVal.calloc(frame)
								.mv_data(frame.bytes(targetKey ? new byte[] { 1, 1 } : new byte[] { 5, 2 }));
						check(mdb_put(writeTxn, rows, key, value, 0));
					}
				}
				putTargetEveryTenth(stack, writeTxn, SMALL, SMALL_RECORDS);
				putTargetEveryTenth(stack, writeTxn, TINY, TINY_RECORDS);
				putTargetEveryTenth(stack, writeTxn, MEDIUM, MEDIUM_RECORDS);
				check(mdb_dbi_open(writeTxn, CLUSTERED, MDB_CREATE, dbi));
				int clustered = dbi.get(0);
				for (int record = 1; record <= CLUSTERED_RECORDS; record++) {
					boolean inCluster = record > CLUSTER_START;
					boolean targetKey = inCluster && record % 10 == 0;
					byte[] content = targetKey ? new byte[] { 1, 1 }
							: inCluster ? new byte[] { 5, 2 } : new byte[] { 5, 0 };
					try (MemoryStack frame = stack.push()) {
						MDBVal key = MDBVal.calloc(frame).mv_data(frame.bytes(key(record, targetKey ? TARGET : OTHER)));
						MDBVal value = MDBVal.calloc(frame).mv_data(frame.bytes(content));
						check(mdb_put(writeTxn, clustered, key, value, 0));
					}
				}
				check(mdb_txn_commit(writeTxn));
				open = false;
			} finally {
				if (open) {
					mdb_txn_abort(writeTxn);
				}
			}
			check(mdb_txn_begin(environment, NULL, MDB_RDONLY, pointer));
			readTxn = pointer.get(0);
		}
		estimator = new LmdbPageCardinalityEstimator(directory.resolve("data.mdb").toFile(), environment, mainDbi);
	}

	/**
	 * Same content as {@link #DATABASE}: every 10th key carries TARGET with one matching row, the rest 5 rows, 2
	 * matching.
	 */
	private static void putTargetEveryTenth(MemoryStack stack, long writeTxn, String name, int records)
			throws IOException {
		try (MemoryStack frame = stack.push()) {
			IntBuffer dbi = frame.mallocInt(1);
			check(mdb_dbi_open(writeTxn, name, MDB_CREATE, dbi));
			for (int record = 1; record <= records; record++) {
				boolean targetKey = record % 10 == 0;
				try (MemoryStack inner = frame.push()) {
					MDBVal key = MDBVal.calloc(inner).mv_data(inner.bytes(key(record, targetKey ? TARGET : OTHER)));
					MDBVal value = MDBVal.calloc(inner)
							.mv_data(inner.bytes(targetKey ? new byte[] { 1, 1 } : new byte[] { 5, 2 }));
					check(mdb_put(writeTxn, dbi.get(0), key, value, 0));
				}
			}
		}
	}

	private static long matchingRowsEveryTenth(int records) {
		return records / 10 + (records - records / 10) * 2L;
	}

	@AfterAll
	void close() throws IOException {
		if (estimator != null) {
			estimator.close();
		}
		if (readTxn != 0) {
			mdb_txn_abort(readTxn);
		}
		if (environment != 0) {
			mdb_env_close(environment);
		}
	}

	@Test
	void decodedLeavesCorrectTheEstimateToRows() throws IOException {
		RangeCountResult corrected = detailed(MEASURE);

		assertThat(corrected.mode).isEqualTo(RangeCountResult.Mode.SAMPLED_RESIDUAL);
		assertThat(corrected.rowsCorrected).isTrue();
		double ratio = corrected.entries / (double) EXACT_MATCHING_ROWS;
		assertThat(ratio).as("corrected %d vs exact %d matching rows", corrected.entries, EXACT_MATCHING_ROWS)
				.isBetween(0.9, 1.1);
		assertThat(corrected.hardLowerBound).isLessThanOrEqualTo(EXACT_MATCHING_ROWS);
		assertThat(corrected.hardUpperBound).isGreaterThanOrEqualTo(EXACT_MATCHING_ROWS);
		assertThat(corrected.decodedLeaves).isBetween(1L, (long) LmdbBtreeRangeCounter.DECODED_LEAF_BUDGET);
	}

	@Test
	void withoutMeasureTheRecordEstimateIsUnchanged() throws IOException {
		RangeCountResult plain = detailed(null);
		RangeCountResult legacy = estimator.estimateEntriesDetailed(mdb_txn_id(readTxn), DATABASE, minKey(),
				minKey().length, maxKey(), maxKey().length, matcher(), 1);

		assertThat(plain.rowsCorrected).isFalse();
		assertThat(plain.decodedLeaves).isZero();
		assertThat(plain.entries).isEqualTo(legacy.entries);
		assertThat(plain.hardLowerBound).isEqualTo(legacy.hardLowerBound);
		assertThat(plain.hardUpperBound).isEqualTo(legacy.hardUpperBound);
		// record estimate: about one matching key in ten
		assertThat(plain.entries / (double) (RECORDS / 10)).isBetween(0.8, 1.2);
	}

	@Test
	void noMatchingRowInTheDecodedLeavesKeepsTheRecordEstimate() throws IOException {
		RangeCountResult plain = detailed(null);
		RangeCountResult fallback = detailed(LmdbChunkRowCorrectionTest::noMatchingRows);

		assertThat(fallback.rowsCorrected).isFalse();
		// the record sample saw matching keys, so every selected leaf is decoded before giving up
		assertThat(fallback.decodedLeaves).isEqualTo(LmdbBtreeRangeCounter.DECODED_LEAF_BUDGET);
		assertThat(fallback.entries).isEqualTo(plain.entries);
		assertThat(fallback.hardUpperBound).isEqualTo(plain.hardUpperBound);
	}

	@Test
	void mappedReadViewReportsRowCorrection() throws IOException {
		try (var view = estimator.readTransaction(readTxn)) {
			LmdbPageCardinalityEstimator.Estimate estimate = view.estimateEntriesWithQuality(DATABASE, minKey(),
					minKey().length, maxKey(), maxKey().length, matcher(), 1, MEASURE);
			assertThat(estimate.rowsCorrected()).isTrue();
			assertThat(estimate.entries()).isEqualTo(detailed(MEASURE).entries);
		}
	}

	@Test
	void patternClusteredInPartOfTheRangeIsCorrected() throws IOException {
		RangeCountResult plain = detailed(CLUSTERED, TARGET, null);
		RangeCountResult corrected = detailed(CLUSTERED, TARGET, MEASURE);

		assertThat(corrected.rowsCorrected).isTrue();
		// Each of the decoded leaves stands for about 1/DECODED_LEAF_BUDGET of the range and the matches fill only
		// its last quarter, so a couple of leaves carry the estimate: allow 25%. The uncorrected record estimate,
		// scaled by the mean rows per record as TripleStore does, is off by about 75%.
		double ratio = corrected.entries / (double) CLUSTERED_MATCHING_ROWS;
		assertThat(ratio).as("corrected %d vs exact %d matching rows", corrected.entries, CLUSTERED_MATCHING_ROWS)
				.isBetween(0.75, 1.25);
		double meanRowsPerRecord = (CLUSTER_START * 5.0 + (CLUSTERED_RECORDS - CLUSTER_START) / 10 * 1.0
				+ (CLUSTERED_RECORDS - CLUSTER_START - (CLUSTERED_RECORDS - CLUSTER_START) / 10) * 5.0)
				/ CLUSTERED_RECORDS;
		double scaledError = Math.abs(plain.entries * meanRowsPerRecord / CLUSTERED_MATCHING_ROWS - 1.0);
		assertThat(Math.abs(ratio - 1.0)).as("corrected error vs scaled record estimate error %.2f", scaledError)
				.isLessThan(scaledError / 2);
	}

	@Test
	void patternAbsentFromSampledKeysAndFirstDecodedLeavesStopsEarly() throws IOException {
		RangeCountResult plain = detailed(CLUSTERED, ABSENT, null);
		RangeCountResult stopped = detailed(CLUSTERED, ABSENT, LmdbChunkRowCorrectionTest::noMatchingRows);

		assertThat(stopped.exhaustive).as("the record sample must not enumerate every leaf").isFalse();
		assertThat(stopped.rowsCorrected).isFalse();
		assertThat(stopped.decodedLeaves).isEqualTo(LmdbBtreeRangeCounter.DECODED_LEAF_EARLY_STOP);
		assertThat(stopped.entries).isEqualTo(plain.entries);
		assertThat(stopped.hardUpperBound).isEqualTo(plain.hardUpperBound);
	}

	@Test
	void exactSmallRangeCountsRowsExactly() throws IOException {
		RangeCountResult plain = detailed(SMALL, TARGET, null);
		RangeCountResult rows = detailed(SMALL, TARGET, MEASURE);

		assertThat(plain.mode).isEqualTo(RangeCountResult.Mode.EXACT_SMALL_RANGE);
		assertThat(plain.entries).isEqualTo(SMALL_RECORDS / 10);
		assertExactRows(rows, RangeCountResult.Mode.EXACT_SMALL_RANGE, matchingRowsEveryTenth(SMALL_RECORDS));
		assertThat(rows.decodedLeaves).isGreaterThan(1L);
	}

	@Test
	void exactSameLeafRangeCountsRowsExactly() throws IOException {
		RangeCountResult rows = detailed(TINY, TARGET, MEASURE);

		assertExactRows(rows, RangeCountResult.Mode.EXACT_SAME_LEAF, matchingRowsEveryTenth(TINY_RECORDS));
		assertThat(rows.decodedLeaves).isEqualTo(1L);
	}

	@Test
	void exactRangeWithoutMatchingRowsIsExactlyZero() throws IOException {
		RangeCountResult rows = detailed(SMALL, TARGET, LmdbChunkRowCorrectionTest::noMatchingRows);

		assertExactRows(rows, RangeCountResult.Mode.EXACT_SMALL_RANGE, 0L);
	}

	@Test
	void exhaustivelySampledRangeIsCorrectedToRows() throws IOException {
		RangeCountResult plain = detailed(MEDIUM, TARGET, null);
		RangeCountResult corrected = detailed(MEDIUM, TARGET, MEASURE);

		assertThat(plain.mode).isEqualTo(RangeCountResult.Mode.SAMPLED_RESIDUAL);
		assertThat(plain.exhaustive).as("the record sample must measure every leaf").isTrue();
		assertThat(plain.entries).isEqualTo(MEDIUM_RECORDS / 10);

		long exact = matchingRowsEveryTenth(MEDIUM_RECORDS);
		assertThat(corrected.rowsCorrected).isTrue();
		// rows are estimated from a spread subset of the leaves, so the result is no longer exact
		assertThat(corrected.exact).isFalse();
		assertThat(corrected.exhaustive).isFalse();
		assertThat(corrected.decodedLeaves).isBetween(1L, (long) LmdbBtreeRangeCounter.DECODED_LEAF_BUDGET);
		double ratio = corrected.entries / (double) exact;
		assertThat(ratio).as("corrected %d vs exact %d matching rows", corrected.entries, exact).isBetween(0.9, 1.1);
		assertThat(corrected.hardLowerBound).isLessThanOrEqualTo(exact);
		assertThat(corrected.hardUpperBound).isGreaterThanOrEqualTo(exact);
	}

	private static void assertExactRows(RangeCountResult result, RangeCountResult.Mode mode, long rows) {
		assertThat(result.mode).isEqualTo(mode);
		assertThat(result.rowsCorrected).isTrue();
		assertThat(result.exact).isTrue();
		assertThat(result.entries).isEqualTo(rows);
		assertThat(result.hardLowerBound).isEqualTo(rows);
		assertThat(result.hardUpperBound).isEqualTo(rows);
	}

	@Test
	void spreadOrderVisitsEveryIndexOnceWithSpreadPrefixes() {
		assertThat(LmdbBtreeRangeCounter.spreadOrder(8)).containsExactly(0, 4, 2, 6, 1, 5, 3, 7);
		assertThat(LmdbBtreeRangeCounter.spreadOrder(5)).containsExactly(0, 4, 2, 1, 3);
		assertThat(LmdbBtreeRangeCounter.spreadOrder(1)).containsExactly(0);
		assertThat(LmdbBtreeRangeCounter.spreadOrder(0)).isEmpty();
	}

	private static long noMatchingRows(ByteBuffer key, ByteBuffer value) {
		return ChunkRowMeasure.pack(value.get(value.position()), 0);
	}

	private RangeCountResult detailed(ChunkRowMeasure measure) throws IOException {
		return detailed(DATABASE, TARGET, measure);
	}

	private RangeCountResult detailed(String database, long predicate, ChunkRowMeasure measure) throws IOException {
		return estimator.estimateEntriesDetailed(mdb_txn_id(readTxn), database, minKey(), minKey().length, maxKey(),
				maxKey().length, matcher(predicate), 1, measure);
	}

	private static GroupMatcher matcher() {
		return matcher(TARGET);
	}

	private static GroupMatcher matcher(long predicate) {
		return new GroupMatcher(key(0, predicate), new boolean[] { false, true, false, false });
	}

	private static byte[] minKey() {
		return key(0, 0);
	}

	private static byte[] maxKey() {
		return encode(Long.MAX_VALUE, Long.MAX_VALUE, Long.MAX_VALUE, Long.MAX_VALUE);
	}

	private static byte[] key(long subject, long predicate) {
		return encode(subject, predicate, 0, 0);
	}

	private static byte[] encode(long... values) {
		ByteBuffer buffer = ByteBuffer.allocate(values.length * 9);
		for (long value : values) {
			Varint.writeUnsigned(buffer, value);
		}
		byte[] bytes = new byte[buffer.position()];
		buffer.flip().get(bytes);
		return bytes;
	}

	private static void check(int result) throws IOException {
		if (result != MDB_SUCCESS) {
			throw new IOException(mdb_strerror(result));
		}
	}
}
